twoway_power <- function(n, a, b, f, df1, alpha) {
  N <- a * b * n
  df2 <- a * b * (n - 1)
  if (df2 <= 0) return(0)
  pf(qf(1 - alpha, df1, df2), df1, df2, ncp = f^2 * N, lower.tail = FALSE)
}

